    private static final Map<String, Integer> BY_NAME = new HashMap<>();
    private static final Map<Material, Integer> CACHE = new ConcurrentHashMap<>();

    static {
        for (String part : DATA) {
            for (String e : part.split(";")) {
                if (e.isEmpty()) continue;
                int i = e.indexOf('=');
                BY_NAME.put(e.substring(0, i), Integer.parseInt(e.substring(i + 1), 16));
            }
        }
    }

    private BlockColors() {}

    /** RGB oder null, wenn der Block nicht in der Tabelle steht. */
    static Integer get(Material m) {
        Integer v = CACHE.get(m);
        if (v == null) {
            Integer c = null;
            try {
                c = BY_NAME.get(m.getKey().getKey());
            } catch (Exception ignored) {
            }
            v = c == null ? -1 : c;
            CACHE.put(m, v);
        }
        return v < 0 ? null : v;
    }
